using System.Globalization;

public abstract class Employee(string name)
{
    public string Name { get; } = name;
    public abstract decimal MonthlyPay();
    protected static decimal Cents(decimal x) => Math.Round(x, 2, MidpointRounding.AwayFromZero);
    protected static string Fmt(decimal x) => x.ToString("F2", CultureInfo.InvariantCulture);
    public virtual string Describe() => $"{Name}: {Fmt(MonthlyPay())}";
}

public class Salaried(string name, decimal yearlySalary) : Employee(name)
{
    public override decimal MonthlyPay() => Cents(yearlySalary / 12);
}

public class Hourly(string name, decimal rate, double hours) : Employee(name)
{
    public override decimal MonthlyPay()
    {
        decimal h = (decimal)hours;
        decimal regular = Math.Min(h, 160m), overtime = Math.Max(h - 160m, 0m);
        return Cents(rate * regular + rate * 1.5m * overtime);
    }

    public override string Describe() => base.Describe() + $" ({hours.ToString(CultureInfo.InvariantCulture)} h)";
}

public class Commissioned(string name, decimal baseSalary, decimal sales, decimal rate) : Salaried(name, baseSalary)
{
    private decimal Commission => Cents(sales * rate);
    public override decimal MonthlyPay() => base.MonthlyPay() + Commission;
    public override string Describe() => base.Describe() + $" (incl. commission {Fmt(Commission)})";
}

public static class Payroll
{
    public static decimal Total(IEnumerable<Employee> staff) => staff.Sum(e => e.MonthlyPay());

    public static string Report(IEnumerable<Employee> staff) =>
        string.Join("\n", staff.OrderByDescending(e => e.MonthlyPay())
                               .ThenBy(e => e.Name, StringComparer.Ordinal)
                               .Select(e => e.Describe()));
}

unitTests:
Test("each kind of pay", () =>
{
    CheckEq(new Salaried("Ada", 60000m).MonthlyPay(), 5000m);
    CheckEq(new Salaried("Bob", 50000m).MonthlyPay(), 4166.67m);
    CheckEq(new Hourly("Cy", 20m, 150).MonthlyPay(), 3000m);
    CheckEq(new Hourly("Di", 20m, 170).MonthlyPay(), 3500m);
    CheckEq(new Commissioned("Ed", 36000m, 10000m, 0.05m).MonthlyPay(), 3500m);
});

Test("polymorphic descriptions", () =>
{
    Employee[] staff = [new Salaried("Ada", 60000m), new Hourly("Cy", 20m, 170.5), new Commissioned("Ed", 36000m, 1234.5m, 0.1m)];
    CheckEq(staff[0].Describe(), "Ada: 5000.00");
    CheckEq(staff[1].Describe(), "Cy: 3515.00 (170.5 h)");
    CheckEq(staff[2].Describe(), "Ed: 3123.45 (incl. commission 123.45)");
    Check(staff[2] is Salaried, "Commissioned should derive from Salaried");
});

Test("payroll", () =>
{
    Employee[] staff = [new Hourly("Zed", 25m, 160), new Salaried("Ada", 48000m), new Salaried("Amy", 48000m)];
    CheckEq(Payroll.Total(staff), 12000m);
    CheckEq(Payroll.Report(staff), "Ada: 4000.00\nAmy: 4000.00\nZed: 4000.00 (160 h)");
    CheckEq(Payroll.Report([]), "");
});

